-- =============================================================================
-- 448 — LE CAHIER D'EXERCICES DE TLE (partie 13)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 448 --niveau Tle --matieres physique-chimie-maths,i2d --suffixe 13 > supabase/contenu/448_exercices_tle_13.sql
--
-- 96 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   i2d.k163                24 exercices · 8 chapitres
--   i2d.k164                24 exercices · 8 chapitres
--   physique-chimie-maths.k187  24 exercices · 8 chapitres
--   physique-chimie-maths.k188  24 exercices · 8 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('f947ad8e-255e-5af6-a101-00ba1a63ed2a'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"L’enceinte nomade sous la loupe","competence":"lire-tableau","situation":"Un bureau d’études chiffre l’impact d’une enceinte Bluetooth sur tout son cycle de vie. Unité fonctionnelle : écouter de la musique 1 h par jour pendant 3 ans.","documents":[{"id":"acv","type":"tableau","titre":"Impact de l’enceinte par phase","colonnes":["Phase","Impact (kg éq. CO2)"],"lignes":[["Fabrication",12],["Transport",2],["Usage",6],["Fin de vie",1]],"enteteLignes":true,"source":"Valeurs simplifiées, écrites pour l’exercice"}],"questions":[{"enonce":"Touche la valeur de la phase qui pèse le plus dans l’impact.","aide":"Cherche le plus grand nombre de la colonne de droite.","type":"zone","document":"acv","multiple":false},{"enonce":"Calcule l’impact total de l’enceinte sur son cycle de vie.","aide":"Additionne les quatre phases.","type":"nombre","unite":"kg éq. CO2"},{"enonce":"Quelle part de l’impact total vient de la fabrication ? Arrondis à l’unité, en pourcentage.","aide":"Divise l’impact de la fabrication par l’impact total.","type":"nombre","unite":"%"},{"enonce":"Quel levier d’éco-conception vise d’abord la phase dominante de cette enceinte ?","aide":"Quelle phase pèse 12 sur 21 ?","type":"choix","options":[{"id":"a","texte":"Réduire le poids de l’emballage, pour alléger la phase de transport"},{"id":"b","texte":"Baisser la consommation en veille, pour réduire la phase d’usage"},{"id":"c","texte":"Rendre l’enceinte recyclable, pour améliorer la phase de fin de vie"},{"id":"d","texte":"Allonger la durée de vie, pour étaler la fabrication sur plus d’années"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"La **fabrication** (12 kg éq. CO2) domine : c’est la phase la plus lourde."},{"cle":{"type":"nombre","valeur":21,"tolerance":0},"affichage":"21 kg éq. CO2","explication":"12 + 2 + 6 + 1 = **21 kg éq. CO2**."},{"cle":{"type":"nombre","valeur":57,"tolerance":0.5},"affichage":"57 %","explication":"12 / 21 ≈ 0,57, soit **57 %**."},{"cle":{"type":"choix","ids":["d"]},"explication":"La fabrication domine : utiliser l’enceinte plus longtemps **répartit cet impact** sur davantage de services rendus."}]$ex$::jsonb),
  ('f947ad8e-255e-5af6-a101-00ba1a63ed2a'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Deux aspirateurs, un seul gagnant","competence":"modeliser","situation":"Un collège compare deux aspirateurs pour l’unité fonctionnelle « aspirer 100 m² chaque semaine pendant 8 ans », soit 208 h d’usage. Le mix électrique français émet 60 g de CO2 par kWh.","documents":[{"id":"asp","type":"tableau","titre":"Les deux candidats","colonnes":["","Aspirateur A","Aspirateur B"],"lignes":[["Puissance (W)",900,650],["Usage sur 8 ans (h)",208,208],["Fabrication (kg éq. CO2)",40,55]],"enteteLignes":true,"source":"Valeurs simplifiées, écrites pour l’exercice"}],"questions":[{"enonce":"Quelle énergie l’aspirateur A consomme-t-il en 8 ans ?","aide":"E = P × t, avec P en kW.","type":"nombre","unite":"kWh"},{"enonce":"Calcule l’impact total de l’aspirateur A (fabrication + usage), arrondi au dixième.","aide":"Usage : 187,2 kWh × 0,06 kg/kWh, puis ajoute la fabrication.","type":"nombre","unite":"kg éq. CO2"},{"enonce":"Calcule l’impact total de l’aspirateur B, arrondi au dixième.","aide":"B consomme 135,2 kWh en 8 ans.","type":"nombre","unite":"kg éq. CO2"},{"enonce":"Avec le mix français, quel aspirateur a le plus faible impact sur le cycle de vie ?","aide":"Compare les deux totaux.","type":"choix","options":[{"id":"a","texte":"Aucun des deux, car l’impact de l’usage est trop faible"},{"id":"b","texte":"L’aspirateur A, dont la fabrication pèse moins que celle de B"},{"id":"c","texte":"Les deux, car leurs impacts sont égaux à un kilo près"},{"id":"d","texte":"L’aspirateur B, qui consomme moins mais coûte plus cher à fabriquer"}],"multiple":false},{"enonce":"Avec un mix très carboné (500 g de CO2 par kWh), quel aspirateur devient le meilleur ?","aide":"Recalcule l’usage avec 0,5 kg par kWh.","type":"choix","options":[{"id":"a","texte":"L’aspirateur A, dont l’impact total monte à 133,6 kg éq. CO2"},{"id":"b","texte":"Les deux restent à égalité, car le mix ne change pas l’usage"},{"id":"c","texte":"L’aspirateur B, dont l’impact total tombe à 122,6 kg éq. CO2"},{"id":"d","texte":"L’aspirateur A, car sa fabrication reste la moins émettrice"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":187.2,"tolerance":0.1},"affichage":"187,2 kWh","explication":"0,9 kW × 208 h = **187,2 kWh**."},{"cle":{"type":"nombre","valeur":51.2,"tolerance":0.1},"affichage":"51,2 kg éq. CO2","explication":"187,2 × 0,06 ≈ 11,2 kg ; 11,2 + 40 = **51,2 kg éq. CO2**."},{"cle":{"type":"nombre","valeur":63.1,"tolerance":0.1},"affichage":"63,1 kg éq. CO2","explication":"135,2 × 0,06 ≈ 8,1 kg ; 8,1 + 55 = **63,1 kg éq. CO2**."},{"cle":{"type":"choix","ids":["b"]},"explication":"A : 51,2 contre 63,1 pour B. Avec une électricité peu carbonée, **la fabrication domine** et A gagne."},{"cle":{"type":"choix","ids":["c"]},"explication":"A : 133,6 kg ; B : 122,6 kg. Quand l’électricité est carbonée, **l’usage domine** et le moins gourmand, B, gagne."}]$ex$::jsonb),
  ('f947ad8e-255e-5af6-a101-00ba1a63ed2a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Gourdes : du neuf ou du recyclé ?","competence":"raisonner","situation":"Une PME fabrique 1 000 gourdes en aluminium de 0,4 kg. Son équipe d’éco-conception note ses travaux en vrac, dans le désordre, avant de présenter son ACV.","documents":[{"id":"notes","type":"fiche","modele":"recette","entete":"Notes de l’équipe","sousTitre":"Carnet de travail, dans le désordre","emoji":"📝","lignes":[{"texte":"Conclure : la fabrication domine, il faut changer de matière","id":"z1"},{"texte":"Mesurer 0,4 kg d’aluminium par gourde","id":"z2"},{"texte":"Définir : boire 1,5 L par jour pendant 5 ans","id":"z3"},{"texte":"Convertir les matières en kg éq. CO2 par kilo","id":"z4"}],"pied":"Aluminium primaire : 10 kg éq. CO2/kg ; recyclé : 1,5 kg éq. CO2/kg (valeurs simplifiées)","teinte":"violet"}],"questions":[{"enonce":"Touche la ligne qui définit l’unité fonctionnelle.","aide":"C’est le service rendu, quantifié.","type":"zone","document":"notes","multiple":false},{"enonce":"Range les quatre étapes de l’ACV dans l’ordre où l’équipe les mène.","aide":"On définit avant de mesurer, et on mesure avant de conclure.","type":"ordre","items":[{"id":"a","texte":"Objectif et unité fonctionnelle"},{"id":"b","texte":"Évaluation des impacts"},{"id":"c","texte":"Inventaire des matières et de l’énergie"},{"id":"d","texte":"Interprétation et choix"}]},{"enonce":"Calcule l’économie d’impact pour UNE gourde si l’on passe de l’aluminium primaire au recyclé.","aide":"Économie par kilo : 10 − 1,5. Multiplie par 0,4 kg.","type":"nombre","unite":"kg éq. CO2"},{"enonce":"Quelle économie pour les 1 000 gourdes, en tonnes éq. CO2 ?","aide":"Multiplie par 1 000, puis convertis les kilos en tonnes.","type":"nombre","unite":"t éq. CO2"},{"enonce":"Quelle phrase justifie correctement le choix de l’aluminium recyclé ?","aide":"Un choix se justifie par un calcul.","type":"choix","options":[{"id":"a","texte":"Il est préférable, car les clients préfèrent la couleur du métal recyclé"},{"id":"b","texte":"Il est préférable, car les concurrents communiquent sur le recyclage"},{"id":"c","texte":"Il est préférable, car l’aluminium recyclé est forcément plus léger"},{"id":"d","texte":"Il est préférable, car le calcul montre une économie de 3,4 kg par gourde"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Définir « boire 1,5 L par jour pendant 5 ans » fixe l’**unité fonctionnelle**, la base de comparaison."},{"cle":{"type":"ordre","ids":["a","c","b","d"]},"explication":"L’ACV suit **objectif, inventaire, évaluation, interprétation**."},{"cle":{"type":"nombre","valeur":3.4,"tolerance":0.05},"affichage":"3,4 kg éq. CO2","explication":"0,4 × (10 − 1,5) = **3,4 kg éq. CO2** par gourde."},{"cle":{"type":"nombre","valeur":3.4,"tolerance":0.05},"affichage":"3,4 t éq. CO2","explication":"3,4 × 1 000 = 3 400 kg = **3,4 t éq. CO2**."},{"cle":{"type":"choix","ids":["d"]},"explication":"On justifie un choix d’éco-conception **par un calcul** et la phase qu’il améliore, jamais par une impression."}]$ex$::jsonb),
  ('fb970bea-7672-5c00-a72a-415c3426f942'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le thermomètre de la serre","competence":"observer-schema","situation":"Dans une serre, une sonde de température mesure 10 mV par °C. Son signal traverse plusieurs étages avant de s’afficher.","documents":[{"id":"ch","type":"chaine","disposition":"ligne","titre":"Chaîne d’information de la serre","noeuds":[{"id":"z1","texte":"Sonde de température","emoji":"🌡️"},{"id":"z2","texte":"Amplificateur (gain 10)"},{"id":"z3","texte":"Convertisseur analogique-numérique"},{"id":"z4","texte":"Microcontrôleur"},{"id":"z5","texte":"Afficheur","emoji":"📟"}],"liens":[{"de":"z1","a":"z2","texte":"tension"},{"de":"z2","a":"z3","texte":"tension"},{"de":"z3","a":"z4","texte":"nombre"},{"de":"z4","a":"z5","texte":"affichage"}],"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche l’étage qui adapte le niveau du signal avant le convertisseur.","aide":"C’est l’étage de conditionnement.","type":"zone","document":"ch","multiple":false},{"enonce":"Relie chaque étage à son rôle.","aide":"Suis le signal de gauche à droite : grandeur, tension, nombre, décision.","type":"association","gauche":[{"id":"g0","texte":"Sonde"},{"id":"g1","texte":"Amplificateur"},{"id":"g2","texte":"CAN"},{"id":"g3","texte":"Microcontrôleur"}],"droite":[{"id":"d0","texte":"Transforme la tension en nombre"},{"id":"d1","texte":"Adapte la tension à la plage du CAN"},{"id":"d2","texte":"Traduit la température en tension"},{"id":"d3","texte":"Traite la mesure et décide"}]},{"enonce":"À 30 °C, quelle tension délivre la sonde, en volts ?","aide":"10 mV par °C : multiplie par 30, puis convertis en volts.","type":"nombre","unite":"V"},{"enonce":"Après l’amplificateur de gain 10, quelle tension arrive au CAN, en volts ?","aide":"Multiplie la tension de la sonde par le gain.","type":"nombre","unite":"V"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"L’**amplificateur** fait partie du conditionnement : il met le signal à l’échelle du CAN."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"Chaque étage a **un seul rôle** : capter, conditionner, convertir, traiter."},{"cle":{"type":"nombre","valeur":0.3,"tolerance":0.001},"affichage":"0,3 V","explication":"30 × 10 mV = 300 mV = **0,3 V**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0.001},"affichage":"3 V","explication":"0,3 × 10 = **3 V**."}]$ex$::jsonb),
  ('fb970bea-7672-5c00-a72a-415c3426f942'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Combien de marches pour un thermomètre ?","competence":"calculer","situation":"Une sonde donne 50 mV par °C (0 V à 0 °C, 5 V à 100 °C). Elle est reliée à un CAN 10 bits de pleine échelle 5 V.","documents":[{"id":"carac","type":"tableau","titre":"Caractéristiques de la chaîne","colonnes":["Grandeur","Valeur"],"lignes":[["Sensibilité de la sonde","50 mV/°C"],["Pleine échelle du CAN","5 V"],["Résolution du CAN","10 bits"],["Nombre de valeurs possibles","2¹⁰ = 1 024"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Calcule le quantum du CAN en millivolts, arrondi au centième.","aide":"q = pleine échelle / 1 024.","type":"nombre","unite":"mV"},{"enonce":"La sonde donne 1,8 V. Quel nombre N le CAN fournit-il ? (partie entière)","aide":"N est la partie entière de U / q, avec q = 5 / 1 024.","type":"nombre"},{"enonce":"Le programme reconstitue U = N × q puis divise par la sensibilité. Quelle température en déduit-il pour N = 368, arrondie au dixième ?","aide":"U = 368 × 5 / 1 024, puis T = U / 0,05.","type":"nombre","unite":"°C"},{"enonce":"Avec un CAN 8 bits (256 valeurs) à la place, quelle résolution en °C, arrondie au centième ?","aide":"Quantum = 5 / 256, à diviser par 0,05 V/°C.","type":"nombre","unite":"°C"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":4.88,"tolerance":0.01},"affichage":"4,88 mV","explication":"5 / 1 024 ≈ **4,88 mV**."},{"cle":{"type":"nombre","valeur":368,"tolerance":0},"affichage":"368","explication":"1,8 / (5 / 1 024) ≈ 368,6 : le CAN garde **368**."},{"cle":{"type":"nombre","valeur":35.9,"tolerance":0.05},"affichage":"35,9 °C","explication":"U ≈ 1,797 V ; T ≈ **35,9 °C**."},{"cle":{"type":"nombre","valeur":0.39,"tolerance":0.005},"affichage":"0,39 °C","explication":"(5 / 256) / 0,05 ≈ **0,39 °C** : la mesure est moins fine."}]$ex$::jsonb),
  ('fb970bea-7672-5c00-a72a-415c3426f942'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le ventilateur qui se trompe","competence":"programmer","situation":"Le programme d’une serre lit la température avec un CAN 10 bits (0 à 5 V pour 0 à 100 °C) et commande un ventilateur. Le technicien teste deux mesures.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"Programme de la serre","auteur":"Programme écrit pour l’exercice","blocs":["n ← lecture du CAN","U ← n × 5 / 1024","T ← U / 0,05","si T est supérieure à 30","    allumer le ventilateur","sinon","    éteindre le ventilateur"]},{"id":"essais","type":"tableau","titre":"Deux mesures de test","colonnes":["Essai","n lu par le CAN"],"lignes":[["A",300],["B",320]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Essai A (n = 300) : quelle température T le programme calcule-t-il, arrondie au dixième ?","aide":"U = 300 × 5 / 1 024 ≈ 1,465 V ; T = U / 0,05.","type":"nombre","unite":"°C"},{"enonce":"Essai B (n = 320) : que fait le ventilateur ?","aide":"Calcule T avec les trois premières lignes.","type":"choix","options":[{"id":"a","texte":"Il s’allume, car T vaut environ 31,3 °C, au-dessus du seuil"},{"id":"b","texte":"Il reste éteint, car T vaut environ 31,3 °C, sous le seuil"},{"id":"c","texte":"Il reste éteint, car T vaut environ 29,3 °C, sous le seuil"},{"id":"d","texte":"Il s’allume, car T vaut environ 28,9 °C, au-dessus du seuil"}],"multiple":false},{"enonce":"Touche le seuil de température du programme.","aide":"C’est le nombre comparé à T.","type":"zone","document":"prog","multiple":false},{"enonce":"Le programmeur utilise des entiers : « n × 5 / 1024 » est une division entière. Quelle valeur prend U pour n = 300 ?","aide":"Calcule 1 500 / 1 024 et garde seulement la partie entière.","type":"nombre","unite":"V"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":29.3,"tolerance":0.05},"affichage":"29,3 °C","explication":"U ≈ 1,465 V, donc T ≈ **29,3 °C**."},{"cle":{"type":"choix","ids":["a"]},"explication":"U = 320 × 5 / 1 024 = 1,5625 V ; T = **31,25 °C**, donc supérieure à 30 : le ventilateur **s’allume**."},{"cle":{"type":"zone","ids":["m17"]},"explication":"Le seuil de déclenchement est **30** (°C)."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1 V","explication":"1 500 / 1 024 ≈ 1,46 : la partie entière vaut **1**. La mesure devient fausse, il faut travailler en flottants."}]$ex$::jsonb),
  ('1e93d6ee-75bb-5f4f-bf3b-11f57521c6a1'::uuid, 1, 1, 5, 20, 3,
