   $ex${"titre":"Le mur de la maison témoin","competence":"calculer","situation":"Une maison témoin a un mur composé de trois couches. L’architecte veut connaître la résistance thermique de l’isolant, puis celle de tout le mur.","documents":[{"id":"mur","type":"tableau","titre":"Composition du mur","colonnes":["Couche","Épaisseur e (cm)","λ (W/m·K)"],"lignes":[["Bloc béton","20","1"],["Polystyrène","12","0,04"],["Plâtre","1","0,25"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche la conductivité thermique λ du polystyrène.","aide":"λ est dans la dernière colonne.","type":"zone","document":"mur","multiple":false},{"enonce":"Calcule la résistance thermique de la couche de polystyrène (convertis e en mètres).","aide":"R = e / λ, avec e = 0,12 m.","type":"nombre","unite":"m²·K/W"},{"enonce":"Calcule la résistance thermique totale du mur (somme des trois couches).","aide":"Béton : 0,20 / 1 ; plâtre : 0,01 / 0,25.","type":"nombre","unite":"m²·K/W"},{"enonce":"Quelle couche apporte l’essentiel de la résistance thermique du mur ?","aide":"Compare les trois R calculés.","type":"choix","options":[{"id":"a","texte":"Les trois couches : chacune apporte à peu près un tiers du total"},{"id":"b","texte":"Le bloc béton : c’est la couche la plus épaisse du mur"},{"id":"c","texte":"Le plâtre : c’est la couche la plus fine, donc la plus isolante"},{"id":"d","texte":"Le polystyrène : 3 m²·K/W sur 3,24 au total"}],"multiple":false}]}$ex$::jsonb,
