  ('33441d30-66aa-5411-92fd-8ea37d0f66de'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Sous le poteau, la semelle","competence":"modeliser","situation":"Un poteau central d’une maison à étage reçoit les charges de trois niveaux, puis les transmet à une semelle isolée posée sur un sol qui admet 0,25 MPa. On néglige le poids du poteau et de la semelle.","documents":[{"id":"ch","type":"tableau","titre":"Charges reprises par le poteau","colonnes":["Charge","Valeur (kN)"],"lignes":[["Toiture et neige","30"],["Plancher haut","45"],["Plancher intermédiaire","55"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"},{"id":"dc","type":"chaine","disposition":"ligne","titre":"Le chemin des charges","noeuds":[{"id":"z1","texte":"Plancher"},{"id":"z2","texte":"Poutre"},{"id":"z3","texte":"Poteau"},{"id":"z4","texte":"Semelle isolée"},{"id":"z5","texte":"Sol"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}],"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Quel effort total N le poteau transmet-il à sa semelle ?","aide":"Additionne les trois charges du tableau.","type":"nombre","unite":"kN"},{"enonce":"Quelle surface de semelle faut-il au minimum ? Réponds en m², arrondi au centième.","aide":"S = N / pression admissible, avec N = 130 000 N et 0,25 MPa = 0,25 N/mm².","type":"nombre","unite":"m²"},{"enonce":"La semelle est carrée. Quel côté minimal, arrondi au centimètre ?","aide":"Le côté est la racine carrée de la surface.","type":"nombre","unite":"m"},{"enonce":"Touche la fondation du bâtiment.","aide":"Une fondation est l’élément en contact avec le sol.","type":"zone","document":"dc","multiple":false},{"enonce":"Le sol est plus mou et n’admet que 0,1 MPa. Que devient la surface de semelle nécessaire ?","aide":"Refais S = N / pression admissible avec 0,1 MPa.","type":"choix","options":[{"id":"a","texte":"Elle devient nulle, car le sol se déforme sous la charge"},{"id":"b","texte":"Elle diminue : un sol mou répartit mieux les charges"},{"id":"c","texte":"Elle augmente : il faut 1,3 m² pour le même poteau"},{"id":"d","texte":"Elle reste de 0,52 m², car l’effort est identique"}],"multiple":false}]}$ex$::jsonb,
