  ('51252a34-afd8-53d2-9c80-a37caf268eb9'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le boîtier qui se creuse","competence":"observer-schema","situation":"Un boîtier en plastique est fabriqué par injection. Sur les premiers exemplaires, une des parois présente un creux à la surface. Le bureau d’études examine la coupe de la pièce.","documents":[{"id":"cp","type":"schema","titre":"Coupe du boîtier injecté","largeur":320,"hauteur":240,"source":"Situation imaginée pour l’exercice","elements":[{"forme":"rect","x":70,"y":50,"l":20,"h":140,"teinte":"gris","motif":"plein","id":"z1","zone":true},{"forme":"rect","x":70,"y":170,"l":200,"h":20,"teinte":"gris","motif":"plein","id":"z2","zone":true},{"forme":"rect","x":210,"y":50,"l":60,"h":140,"teinte":"gris","motif":"plein","id":"z3","zone":true},{"forme":"texte","x":80,"y":38,"texte":"2 mm","ancre":"milieu","taille":"petit"},{"forme":"texte","x":240,"y":38,"texte":"6 mm","ancre":"milieu","taille":"petit"},{"forme":"texte","x":170,"y":212,"texte":"2 mm","ancre":"milieu","taille":"petit"}]},{"id":"cout","type":"tableau","titre":"Coût de production","colonnes":["Coût du moule","Coût par pièce","Quantité"],"lignes":[["12 000 €","1,10 €","20 000"]],"enteteLignes":false,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche la paroi qui provoquera des retassures.","aide":"Une paroi beaucoup plus épaisse que les autres refroidit plus lentement.","type":"zone","document":"cp","multiple":false},{"enonce":"Combien de fois la paroi de droite est-elle plus épaisse que celle de gauche ?","aide":"Divise 6 mm par 2 mm.","type":"nombre","unite":"fois"},{"enonce":"Quelle correction de forme convient le mieux ?","aide":"Une épaisseur constante évite les retassures.","type":"choix","options":[{"id":"a","texte":"Épaissir aussi les autres parois jusqu’à 10 mm partout"},{"id":"b","texte":"Supprimer les congés pour faciliter l’écoulement du plastique"},{"id":"c","texte":"Ramener la paroi à 2 mm et la renforcer par des nervures"},{"id":"d","texte":"Garder 6 mm et ralentir le refroidissement du moule"}],"multiple":false},{"enonce":"Quel est le coût total des 20 000 pièces (moule compris) ?","aide":"Coût total = moule + quantité × coût par pièce.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La paroi de droite, épaisse de 6 mm, refroidit plus lentement : c’est elle qui fait des **retassures**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 fois","explication":"6 / 2 = **3 fois**."},{"cle":{"type":"choix","ids":["c"]},"explication":"On garde une **épaisseur constante** et on rigidifie avec des nervures, sans épaissir la paroi."},{"cle":{"type":"nombre","valeur":34000,"tolerance":0},"affichage":"34 000 €","explication":"12 000 + 20 000 × 1,10 = **34 000 €**."}]$ex$::jsonb),
  ('51252a34-afd8-53d2-9c80-a37caf268eb9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quel procédé pour la poignée ?","competence":"resoudre","situation":"Un fabricant de vélos doit produire une poignée de frein en plastique. Trois procédés sont possibles ; leur coût dépend du nombre de pièces à fabriquer.","documents":[{"id":"pr","type":"tableau","titre":"Les trois procédés","colonnes":["Procédé","Coût fixe","Coût par pièce"],"lignes":[["Usinage","1 500 €","12 €"],["Fabrication additive","0 €","8 €"],["Injection plastique","18 000 € (moule)","1,50 €"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"},{"id":"cr","type":"graphique","forme":"courbe","titre":"Coût total selon la quantité","categories":["0","1 000","2 000","3 000","4 000"],"series":[{"nom":"Injection plastique","valeurs":[18000,19500,21000,22500,24000],"teinte":"violet"},{"nom":"Fabrication additive","valeurs":[0,8000,16000,24000,32000],"teinte":"corail"}],"axeY":{"titre":"Coût total","unite":"€","min":0,"max":35000,"pas":5000},"axeX":{"titre":"Nombre de pièces"},"source":"Calculé avec les valeurs du tableau"}],"questions":[{"enonce":"Quel est le coût total de 500 pièces en fabrication additive ?","aide":"Coût total = coût fixe + quantité × coût par pièce.","type":"nombre","unite":"€"},{"enonce":"Pour 5 000 pièces, quel procédé est le moins cher ?","aide":"Calcule le coût total des trois procédés.","type":"choix","options":[{"id":"a","texte":"L’injection plastique : 25 500 € au total pour 5 000 pièces"},{"id":"b","texte":"Les trois coûtent le même prix dès que la série dépasse 4 000 pièces"},{"id":"c","texte":"La fabrication additive : 40 000 € au total pour 5 000 pièces"},{"id":"d","texte":"L’usinage : 61 500 € au total pour 5 000 pièces"}],"multiple":false},{"enonce":"Touche la première quantité pour laquelle l’injection coûte moins cher que la fabrication additive.","aide":"Cherche où la courbe de l’injection passe sous celle de l’additive.","type":"zone","document":"cr","multiple":false},{"enonce":"À partir de combien de pièces (nombre entier) l’injection devient-elle moins chère que la fabrication additive ?","aide":"Résous 18 000 + 1,5 × n < 8 × n.","type":"nombre","unite":"pièces"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":4000,"tolerance":0},"affichage":"4000 €","explication":"0 + 500 × 8 = **4 000 €**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Injection : 18 000 + 5 000 × 1,5 = **25 500 €**, contre 40 000 € (additive) et 61 500 € (usinage)."},{"cle":{"type":"zone","ids":["k3"]},"explication":"À **3 000 pièces**, l’injection (22 500 €) passe sous l’additive (24 000 €)."},{"cle":{"type":"nombre","valeur":2770,"tolerance":0},"affichage":"2770 pièces","explication":"18 000 / 6,5 ≈ 2 769,2 : dès **2 770 pièces**, l’injection est moins chère."}]$ex$::jsonb),
  ('51252a34-afd8-53d2-9c80-a37caf268eb9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Alléger le support de caméra","competence":"analyser-document","situation":"Un fabricant remplace un support de caméra en aluminium usiné par une version en polyamide injecté, conçue avec un logiciel d’optimisation topologique. Il veut chiffrer le gain pour 10 000 supports par an.","documents":[{"id":"cmp","type":"tableau","titre":"Les deux solutions","colonnes":["Critère","Solution A","Solution B"],"lignes":[["Matériau","Aluminium usiné","Polyamide injecté"],["Masse","0,48 kg","0,30 kg"],["Nombre de pièces","7","3"],["Assemblage","6 vis","Clips démontables"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"},{"id":"emp","type":"tableau","titre":"Empreinte carbone des matériaux","colonnes":["Matériau","Empreinte (kg CO₂e par kg)"],"lignes":[["Aluminium usiné","9"],["Polyamide injecté","6"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Touche le nombre de pièces de la solution B.","aide":"Lis la ligne « Nombre de pièces », colonne « Solution B ».","type":"zone","document":"cmp","multiple":false},{"enonce":"De quel pourcentage la masse diminue-t-elle entre A et B ? Arrondi au dixième.","aide":"Gain = (0,48 − 0,30) / 0,48.","type":"nombre","unite":"%"},{"enonce":"Quelle est l’empreinte carbone de la matière d’un support A ?","aide":"Empreinte = masse × empreinte par kg.","type":"nombre","unite":"kg CO₂e"},{"enonce":"Un support B a une empreinte de 1,8 kg CO₂e. Pour 10 000 supports, combien de tonnes de CO₂e évite-t-on par rapport à A ?","aide":"Gain par support × 10 000, puis divise par 1 000 pour passer en tonnes.","type":"nombre","unite":"t CO₂e"},{"enonce":"Sur le plan de l’éco-conception, que montre aussi le tableau en faveur de la solution B ?","aide":"Regarde les lignes « Nombre de pièces » et « Assemblage ».","type":"choix","options":[{"id":"a","texte":"Des clips démontables et peu de pièces facilitent réparation et recyclage"},{"id":"b","texte":"Un plus grand nombre de pièces, ce qui rend le démontage plus simple"},{"id":"c","texte":"Un matériau plus lourd, donc plus facile à recycler en fin de vie"},{"id":"d","texte":"Un assemblage par six vis, jugé plus durable qu’un clip dans tous les cas"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"La solution B n’a que **3 pièces**, contre 7 pour la A."},{"cle":{"type":"nombre","valeur":37.5,"tolerance":0.1},"affichage":"37,5 %","explication":"0,18 / 0,48 = **37,5 %** de masse en moins."},{"cle":{"type":"nombre","valeur":4.32,"tolerance":0.01},"affichage":"4,32 kg CO₂e","explication":"0,48 × 9 = **4,32 kg CO₂e**."},{"cle":{"type":"nombre","valeur":25.2,"tolerance":0.1},"affichage":"25,2 t CO₂e","explication":"(4,32 − 1,8) × 10 000 = 25 200 kg, soit **25,2 tonnes**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Moins de pièces et des **clips démontables** : la réparation et le tri en fin de vie sont plus simples."}]$ex$::jsonb),
  ('7cb44eba-8094-52a0-80ca-2c337dfe27f0'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Du capteur au serveur","competence":"analyser-document","situation":"Un capteur de température est placé dans un champ. Sa mesure est traitée par une carte, puis envoyée par radio à un serveur qui garde l’historique.","documents":[{"id":"ob","type":"chaine","disposition":"ligne","titre":"Le trajet de la mesure","noeuds":[{"id":"z1","texte":"Capteur de température"},{"id":"z2","texte":"Convertisseur analogique-numérique (CAN)"},{"id":"z3","texte":"Microcontrôleur"},{"id":"z4","texte":"Module radio"},{"id":"z5","texte":"Serveur"}],"liens":[{"de":"z1","a":"z2","texte":"tension"},{"de":"z2","a":"z3","texte":"nombre"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Touche le constituant qui transforme la tension du capteur en nombre.","aide":"Il passe de l’analogique au numérique.","type":"zone","document":"ob","multiple":false},{"enonce":"Le CAN a 10 bits et mesure de 0 à 5 V. Il fournit n = 512. Quelle tension cela représente-t-il ?","aide":"U = n × 5 / 1 024.","type":"nombre","unite":"V"},{"enonce":"Relie chaque composant à la bonne entrée-sortie de la carte.","aide":"Pense à ce que chaque composant échange : 0/1, une tension, une intensité réglable, des données.","type":"association","gauche":[{"id":"g0","texte":"Bouton poussoir"},{"id":"g1","texte":"Thermistance"},{"id":"g2","texte":"LED dimmable"},{"id":"g3","texte":"Écran OLED"}],"droite":[{"id":"d0","texte":"Entrée analogique (CAN)"},{"id":"d1","texte":"Entrée numérique (TOR)"},{"id":"d2","texte":"Sortie MLI"},{"id":"d3","texte":"Bus I2C"}]},{"enonce":"Le capteur doit envoyer quelques octets toutes les 15 min, à 2 km, en fonctionnant sur piles. Quel module radio choisir ?","aide":"Portée, débit et consommation : que faut-il ici ?","type":"choix","options":[{"id":"a","texte":"LoRa : longue portée et très faible consommation pour de petits messages"},{"id":"b","texte":"Aucun : il faut obligatoirement un câble jusqu’au serveur"},{"id":"c","texte":"Bluetooth : portée de 2 km garantie avec un très faible débit"},{"id":"d","texte":"Wi-Fi : portée de 2 km grâce à son débit élevé et sa consommation faible"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le **CAN** convertit une tension en un nombre binaire."},{"cle":{"type":"nombre","valeur":2.5,"tolerance":0},"affichage":"2,5 V","explication":"U = 512 × 5 / 1 024 = **2,5 V**."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"Le bouton donne du **tout ou rien**, la thermistance une tension qu’on convertit, la LED dimmable se règle en **MLI**, l’écran dialogue sur un **bus I2C**."},{"cle":{"type":"choix","ids":["a"]},"explication":"**LoRa** est fait pour les petits messages envoyés loin avec très peu d’énergie."}]$ex$::jsonb),
  ('7cb44eba-8094-52a0-80ca-2c337dfe27f0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La pompe de la serre","competence":"programmer","situation":"Le programme d’une serre arrose quand le sol est sec. La mesure est faite toutes les heures, et la pompe est à l’arrêt au départ. Le technicien relève six mesures.","documents":[{"id":"pg","type":"texte","genre":"consigne","titre":"Programme de la serre","auteur":"Programme écrit pour l’exercice","blocs":["tant que vrai :","    h ← lire_humidite()","    si h < 40 alors","        pompe ← MARCHE","    sinon si h > 60 alors","        pompe ← ARRET"]},{"id":"me","type":"tableau","titre":"Les six mesures d’humidité","colonnes":["Mesure","1","2","3","4","5","6"],"lignes":[["h (%)","55","45","38","42","59","62"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche le seuil qui déclenche la mise en marche de la pompe.","aide":"La pompe démarre quand le sol est trop sec.","type":"zone","document":"pg","multiple":false},{"enonce":"Trie les mesures selon l’état de la pompe juste après le traitement de chacune.","aide":"Entre 40 et 60 %, la pompe garde l’état qu’elle avait.","type":"categories","categories":[{"id":"c0","texte":"Pompe en marche"},{"id":"c1","texte":"Pompe à l’arrêt"}],"items":[{"id":"i0","texte":"Mesure 4 (42 %)"},{"id":"i1","texte":"Mesure 1 (55 %)"},{"id":"i2","texte":"Mesure 5 (59 %)"},{"id":"i3","texte":"Mesure 6 (62 %)"},{"id":"i4","texte":"Mesure 2 (45 %)"},{"id":"i5","texte":"Mesure 3 (38 %)"}]},{"enonce":"Pourquoi le programme utilise-t-il deux seuils (40 et 60) plutôt qu’un seul à 50 ?","aide":"Imagine une humidité qui oscille autour de 50 %.","type":"choix","options":[{"id":"a","texte":"Pour obliger la pompe à fonctionner au moins une heure par jour"},{"id":"b","texte":"Pour que le capteur d’humidité mesure avec plus de précision dans le sol"},{"id":"c","texte":"Pour éviter que la pompe démarre et s’arrête sans cesse autour d’un seuil unique"},{"id":"d","texte":"Pour économiser de la mémoire du microcontrôleur en stockant moins de valeurs"}],"multiple":false},{"enonce":"Le sol est à 59 % et sèche de 2 points par heure. Au bout de combien d’heures la pompe démarre-t-elle ?","aide":"Il faut que h passe strictement sous 40.","type":"nombre","unite":"h"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"La pompe démarre quand **h < 40**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c1","i5":"c0"}},"explication":"Elle démarre à **38 %**, reste en marche à **42 %** et **59 %**, puis s’arrête à **62 %** ; avant, elle était à l’arrêt."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est une **hystérésis** : entre 40 et 60 %, on ne change rien, ce qui évite les démarrages répétés."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 h","explication":"Après 9 h, h = 41 ; après **10 h**, h = 39 < 40 : la pompe démarre."}]$ex$::jsonb),
  ('7cb44eba-8094-52a0-80ca-2c337dfe27f0'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le portail qui doit s’arrêter","competence":"programmer","situation":"Un portail doit s’arrêter en moins de 0,5 s après avoir détecté un obstacle. L’arrêt du moteur prend 200 ms une fois l’ordre donné. Un tour de la boucle ci-dessous dure 350 ms à cause de l’affichage et du clavier.","documents":[{"id":"bc","type":"texte","genre":"consigne","titre":"Version avec lecture dans la boucle","auteur":"Programme écrit pour l’exercice","blocs":["tant que vrai :","    obstacle ← lire_cellule()","    si obstacle alors","        arreter_moteur()","    afficher_etat()","    lire_clavier()"]},{"id":"es","type":"tableau","titre":"Version avec interruption : 5 essais au banc","colonnes":["Essai","1","2","3","4","5"],"lignes":[["Temps d’arrêt mesuré (s)","0,21","0,22","0,21","0,23","0,22"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche l’instruction qui lit la cellule de détection.","aide":"Le nom de la fonction dit ce qu’elle lit.","type":"zone","document":"bc","multiple":true},{"enonce":"Dans le pire cas, l’obstacle apparaît juste après la lecture : il faut attendre un tour de boucle complet. Quel est le temps d’arrêt ?","aide":"Un tour de boucle (350 ms) puis l’arrêt du moteur (200 ms).","type":"nombre","unite":"ms"},{"enonce":"Avec une interruption, la réaction prend 10 ms avant l’ordre d’arrêt. Quel est le temps d’arrêt ?","aide":"Réaction de 10 ms puis arrêt du moteur de 200 ms.","type":"nombre","unite":"ms"},{"enonce":"Que conclure des cinq essais au banc avec interruption ?","aide":"Compare la mesure la plus élevée à l’exigence.","type":"choix","options":[{"id":"a","texte":"Conforme : le maximum mesuré de 0,23 s reste sous les 0,5 s exigés"},{"id":"b","texte":"Non conforme : les cinq mesures sont toutes différentes entre elles"},{"id":"c","texte":"Non conforme : 0,23 s dépasse la valeur calculée de 210 ms"},{"id":"d","texte":"Indéterminé : il faudrait au moins cent essais pour conclure"}],"multiple":false}]}$ex$::jsonb,
