   $ex${"titre":"La batterie de la trottinette","competence":"calculer","situation":"Dans un sujet de bac, on demande de vérifier l’exigence d’autonomie d’une trottinette électrique. Voici les données du dossier technique.","documents":[{"id":"dt","type":"tableau","titre":"Extrait du dossier technique","colonnes":["Donnée","Valeur"],"lignes":[["Tension de la batterie","36 V"],["Capacité","10 Ah"],["Consommation moyenne","250 W"],["Autonomie exigée","2 h"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche la capacité de la batterie.","aide":"La capacité s’exprime en ampères-heures.","type":"zone","document":"dt","multiple":false},{"enonce":"Quelle énergie la batterie stocke-t-elle ?","aide":"E = U × Q : écris la formule, puis l’application numérique.","type":"nombre","unite":"Wh"},{"enonce":"Quelle autonomie cela donne-t-il à 250 W de consommation moyenne ? Arrondi au centième d’heure.","aide":"Autonomie = énergie / puissance.","type":"nombre","unite":"h"},{"enonce":"Quelle phrase de conclusion rapporte tous les points ?","aide":"Compare ton résultat au critère du cahier des charges.","type":"choix","options":[{"id":"a","texte":"Exigence non satisfaite : la batterie stocke 360 Wh et c’est peu"},{"id":"b","texte":"Exigence non satisfaite : 1,44 h est inférieure aux 2 h exigées"},{"id":"c","texte":"Exigence satisfaite : la trottinette consomme seulement 250 W"},{"id":"d","texte":"Exigence satisfaite : 1,44 h est proche de 2 h, donc suffisante"}],"multiple":false}]}$ex$::jsonb,
