   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Dans les **capteurs**, la lumière absorbée est convertie en chaleur."},{"cle":{"type":"nombre","valeur":3200,"tolerance":10},"affichage":"3200 W","explication":"P = 800 × 4,0 = **3 200 W**."},{"cle":{"type":"nombre","valeur":1920,"tolerance":10},"affichage":"1920 W","explication":"P utile = 0,60 × 3 200 = **1 920 W**."},{"cle":{"type":"nombre","valeur":18.8,"tolerance":0.1},"affichage":"18,8 MJ","explication":"Q = 150 × 4 180 × 30 = 18 810 000 J ≈ **18,8 MJ**."},{"cle":{"type":"nombre","valeur":2.72,"tolerance":0.02},"affichage":"2,72 h","explication":"t = 18 810 000 / 1 920 ≈ 9 797 s, soit environ **2,72 h** (2 h 43)."}]$ex$::jsonb),
  ('ab76b534-f184-5969-9ac7-8185f53665c0'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le fluor 18 de l’hôpital","competence":"lire-tableau","situation":"Pour un examen d’imagerie médicale, un service de médecine nucléaire prépare du fluor 18, radioactif. Un technicien relève l’activité de la dose au cours du temps.","documents":[{"id":"act","type":"tableau","titre":"Activité d’une dose de fluor 18","colonnes":["Temps (min)","0","110","220","330","440"],"lignes":[["Activité (MBq)","400","200","100","?","25"]],"enteteLignes":false}],"questions":[{"enonce":"Touche l’activité qui vaut le quart de l’activité initiale.","aide":"Le quart de 400 MBq : divise 400 par 4.","type":"zone","document":"act","multiple":false},{"enonce":"Déduis du tableau la demi-vie du fluor 18, en minutes.","aide":"La demi-vie est la durée pour que l’activité soit divisée par 2.","type":"nombre","unite":"min"},{"enonce":"Complète la case « ? » : quelle est l’activité à 330 min, en MBq ?","aide":"Entre 220 min et 330 min, combien de demi-vies passent-elles ?","type":"nombre","unite":"MBq"},{"enonce":"Quel pourcentage de l’activité initiale reste-t-il à 440 min ? Arrondis au centième.","aide":"Divise l’activité à 440 min par l’activité initiale.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c3"]},"explication":"400 / 4 = 100 MBq : c’est la case de **220 min**."},{"cle":{"type":"nombre","valeur":110,"tolerance":1},"affichage":"110 min","explication":"L’activité passe de 400 à 200 MBq en 110 min : la demi-vie est de **110 min**."},{"cle":{"type":"nombre","valeur":50,"tolerance":0.5},"affichage":"50 MBq","explication":"Encore une demi-vie : 100 / 2 = **50 MBq**."},{"cle":{"type":"nombre","valeur":6.25,"tolerance":0.05},"affichage":"6,25 %","explication":"25 / 400 = 0,0625, soit **6,25 %** : 440 min, c’est quatre demi-vies."}]$ex$::jsonb),
  ('ab76b534-f184-5969-9ac7-8185f53665c0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Compléter les équations nucléaires","competence":"analyser-document","situation":"Un manuel de physique présente trois désintégrations. Dans chaque équation, le nombre de nucléons A et la charge Z se conservent.","documents":[{"id":"part","type":"tableau","titre":"Les particules émises","colonnes":["Type","Particule émise","A","Z"],"lignes":[["α","Noyau d’hélium","4","2"],["β⁻","Électron","0","−1"],["β⁺","Positon","0","+1"]],"enteteLignes":false},{"id":"des","type":"tableau","titre":"Trois désintégrations","colonnes":["Noyau père","Type","Noyau fils"],"lignes":[["Uranium 238 (A = 238, Z = 92)","α","Thorium (A = ?, Z = 90)"],["Carbone 14 (A = 14, Z = 6)","β⁻","Azote (A = 14, Z = ?)"],["Fluor 18 (A = 18, Z = 9)","β⁺","Oxygène (A = 18, Z = ?)"]],"enteteLignes":false}],"questions":[{"enonce":"Touche les deux types de rayonnement qui n’emportent aucun nucléon (A = 0).","aide":"Regarde la colonne A du tableau des particules.","type":"zone","document":"part","multiple":true},{"enonce":"Quel est le nombre de masse A du thorium formé ?","aide":"A se conserve : 238 = A + 4.","type":"nombre"},{"enonce":"Quel est le numéro atomique Z de l’azote formé ?","aide":"La charge se conserve : 6 = Z + (−1).","type":"nombre"},{"enonce":"Quel est le numéro atomique Z de l’oxygène formé ?","aide":"La charge se conserve : 9 = Z + (+1).","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0","r2c0"]},"explication":"Les **β⁻ et β⁺** ont A = 0 : électron et positon ne sont pas des nucléons."},{"cle":{"type":"nombre","valeur":234,"tolerance":0},"affichage":"234","explication":"A = 238 − 4 = **234**."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7","explication":"Z = 6 + 1 = **7** : un électron emporte une charge −1."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8","explication":"Z = 9 − 1 = **8** : le positon emporte une charge +1."}]$ex$::jsonb),
  ('ab76b534-f184-5969-9ac7-8185f53665c0'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"L’iode 131 de la thyroïde","competence":"modeliser","situation":"Un patient reçoit de l’iode 131 pour soigner sa thyroïde. Le graphique montre la part des noyaux radioactifs restants ; la fiche donne la loi de décroissance.","documents":[{"id":"gr","type":"graphique","forme":"courbe","titre":"Noyaux d’iode 131 restants","categories":["0","8","16","24","32","40"],"series":[{"nom":"Part restante","valeurs":[100,50,25,12.5,6.25,3.125],"teinte":"turquoise"}],"axeY":{"titre":"Noyaux restants","unite":"%","min":0,"max":100,"pas":20},"axeX":{"titre":"Temps (jours)"}},{"id":"loi","type":"fiche","modele":"panneau","entete":"Décroissance radioactive","sousTitre":"Loi à utiliser","emoji":"☢️","lignes":[{"texte":"N(t) = N0 × e^(−λ × t)","valeur":"","gras":true},{"texte":"λ = ln 2 / t½","valeur":"","gras":true},{"separateur":true},{"texte":"t½ (iode 131)","valeur":"8,0 jours"}]}],"questions":[{"enonce":"Touche l’instant où il reste 12,5 % des noyaux.","aide":"Cherche le point de la courbe à 12,5 %.","type":"zone","document":"gr","multiple":false},{"enonce":"Calcule la constante radioactive λ de l’iode 131, en jour⁻¹, arrondie au dix-millième.","aide":"λ = ln 2 / t½, avec t½ = 8,0 jours.","type":"nombre","unite":"jour⁻¹"},{"enonce":"Quel pourcentage des noyaux reste-t-il au bout de 30 jours ? Arrondis au dixième.","aide":"N / N0 = e^(−λ × t), avec t = 30 jours.","type":"nombre","unite":"%"},{"enonce":"Au bout de combien de jours reste-t-il 1 % des noyaux ? Arrondis au dixième.","aide":"Résous e^(−λ × t) = 0,01, donc t = ln 100 / λ.","type":"nombre","unite":"jours"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"À **24 jours**, il reste 12,5 % des noyaux : c’est trois demi-vies."},{"cle":{"type":"nombre","valeur":0.0866,"tolerance":0.0005},"affichage":"0,0866 jour⁻¹","explication":"λ = 0,693 / 8,0 ≈ **0,0866 jour⁻¹**."},{"cle":{"type":"nombre","valeur":7.4,"tolerance":0.1},"affichage":"7,4 %","explication":"N / N0 = e^(−0,0866 × 30) ≈ 0,074, soit **7,4 %** : entre 6,25 % (32 j) et 12,5 % (24 j), comme le graphique."},{"cle":{"type":"nombre","valeur":53.2,"tolerance":0.3},"affichage":"53,2 jours","explication":"t = ln 100 / 0,0866 ≈ **53,2 jours**, soit un peu plus de six demi-vies."}]$ex$::jsonb),
