  ('115f0938-8cac-506b-a73f-76d925aa539b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Du glaçon à l’eau tiède","competence":"calculer","situation":"Dans un laboratoire, on chauffe 0,30 kg de glace prise à −20 °C jusqu’à obtenir de l’eau liquide à 50 °C. Le tableau détaille les trois étapes ; la première est déjà calculée.","documents":[{"id":"eta","type":"tableau","titre":"Les trois étapes du chauffage","colonnes":["Étape","Calcul","Énergie (kJ)"],"lignes":[["Glace de −20 °C à 0 °C","m × c glace × 20","12,6"],["Fusion à 0 °C","m × L fusion","?"],["Eau de 0 °C à 50 °C","m × c eau × 50","?"]],"enteteLignes":false},{"id":"cst","type":"fiche","modele":"panneau","entete":"Données","sousTitre":"Pour cet exercice","emoji":"🧊","lignes":[{"texte":"c glace","valeur":"2 100 J/(kg·°C)"},{"texte":"c eau","valeur":"4 180 J/(kg·°C)"},{"texte":"L fusion","valeur":"334 kJ/kg"}]}],"questions":[{"enonce":"Touche l’étape pendant laquelle la température ne change pas.","aide":"Pendant un changement d’état, l’énergie sert à rompre des liaisons, pas à chauffer.","type":"zone","document":"eta","multiple":false},{"enonce":"Calcule l’énergie de la fusion de 0,30 kg de glace, en kJ.","aide":"Q = m × L fusion, avec L = 334 kJ/kg.","type":"nombre","unite":"kJ"},{"enonce":"Calcule l’énergie pour chauffer l’eau de 0 °C à 50 °C, en kJ, arrondie au dixième.","aide":"Q = m × c eau × ΔT en joules, puis divise par 1 000.","type":"nombre","unite":"kJ"},{"enonce":"Calcule l’énergie totale à fournir, en kJ.","aide":"Additionne les trois étapes.","type":"nombre","unite":"kJ"}]}$ex$::jsonb,
